import { Dropzone } from '@dropzone-ui/react';
import { Property } from '@stitches/react/types/css';
import { Action } from '../alert/Alert.types';

// eslint-disable-next-line @typescript-eslint/ban-types
type ExtractProps<T> = T extends React.Component<infer P> | React.FC<infer P> ? P : never;

type DropzoneTypes = ExtractProps<typeof Dropzone>;
type DropzoneProps = Omit<DropzoneTypes, 'style' | 'header' | 'footer'>;
type ImageUploaderType = {
  imageUrl: string;
  alt: string;
};

type NonImageUploaderType = {
  imageUrl?: never;
  alt?: never;
};

export type FileUploaderType = (ImageUploaderType | NonImageUploaderType) & {
  type?: 'image' | 'document' | 'file';
  error?: {
    message: string;
    action?: Action;
  };
  message: string;
  buttonIntl?: string;
  imageHeight?: string;
  imageFit?: Property.ObjectFit;
} & DropzoneProps;

export interface CustomValidateFileResponse {
  valid: boolean;
  errors?: string[];
}
